"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9628"],{3232(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>h,frontMatter:()=>i,contentTitle:()=>s,toc:()=>u,assets:()=>l});var n=JSON.parse('{"id":"reference/register/howtos/StagingMultipleAirLinkGateways","title":"How to Stage Multiple AirLink Routers or Gateways at One Time Using a Switch and an ALMS Template","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/register/howtos/StagingMultipleAirLinkGateways.md","sourceDirName":"reference/register/howtos","slug":"/reference/register/howtos/StagingMultipleAirLinkGateways","permalink":"/personal-av-docs/docs/reference/register/howtos/StagingMultipleAirLinkGateways","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/register/howtos/StagingMultipleAirLinkGateways.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to Stage Multiple AirLink Routers or Gateways at One Time Using a Switch and an ALMS Template","sidebar_label":"How to Stage Multiple AirLink Routers or","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/register/howtos/StagingMultipleAirLinkGateways","format":"md"}}'),o=a(4848),r=a(8453);let i={title:"How to Stage Multiple AirLink Routers or Gateways at One Time Using a Switch and an ALMS Template",sidebar_label:"How to Stage Multiple AirLink Routers or",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/register/howtos/StagingMultipleAirLinkGateways",format:"md"},s,l={},u=[];function c(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/register/howtos/StagingMultipleAirLinkGateways",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:"How to Stage Multiple AirLink Routers or Gateways at One Time Using a Switch and an ALMS Template\nThe Problem? How to Most Efficiently Configure Multiple AirLink Routers or Gateways?\nOne of the common problems that our Partners and Customers experience is how to quickly and easily configure dozens, or even hundreds of AirLink routers or gateways before sending them out to be deployed in the field. Most of our users are familiar with ACEmanager, the ALEOS configuration tool that we use to configure the software on the gateway. But using ACEmanager to manually configure even dozens of devices is a time-consuming and inefficient process for configuration before deployment. In addition, by doing an initial firmware update over Ethernet from AirLink Management Service (ALMS), you are not using any cellular data which would be required if you waited for the devices to be deployed before completing the update. This could be significant for Customers on limited data plans.\nThis document describes a way to preconfigure your AirLink gateways or routers via the Ethernet port on the gateway or router by connecting multiple devices to an Ethernet switch connected to the Internet, and using ALMS and a template to configure the devices.\nPrerequisites and Assumptions\nBefore getting started with this project, there are a number of things that you need to have in place:\nAn ALMS Account with at least one active user\nIf you do not have an ALMS account, you can create an account to try this process. Sign-up for your ALMS account\nhere\n.\nMultiple AirLink Gateways\nFor this example, we have 11 RV50 AirLink gateways with no SIM cards.\nWhile you could do this exercise with gateways with SIM cards installed, the process is easier without them.\nAt least one active gateway of the same type registered into the account. Make sure you have performed at least one complete synchronization of the gateway with ALMS to ensure all of the relevant details are on the platform.\nThis will ensure that the firmware version(s) you require are active in the account, and that you can create a template against this firmware version.\nAn ALMS template with the device configuration. There are two ways you can create a template to use:\nCreate from scratch in ALMS: Use ALMS to create a new template, and configure all the required parameters.\nConfigure a gateway with ACEmanager, sync to ALMS: You can then use that gateway to create a template with all of the parameters you have configured.\nEither process will work; you just have to decide which process is best for you. For detailed instructions, log into ALMS and follow the instructions in the documentation:\nHow to create a template?\nHow to review and edit a template or dataset?\nPlease note that a saved template file from ACEmanager cannot be used in ALMS.\nRegister your List of Gateways or Routers\nThe first step is to pre-register your devices with ALMS.\nLog into ALMS.\nClick the\nRegister\ntab.\nClick\nImport a list\n.\nALMS opens a new dialog box, where you can click\nDownload template\nto download the .CSV file you will populate.\nOnce the template is downloaded, you will need to take your fleet of gateways and populate the IMEI, Serial Number, Password, Friendly Name for the gateway and any labels you want to apply in ALMS.\nIn the above example, we have populated information that does not conform to the standards required for an AirLink gateway, and have masked any passwords. To populate IMEI and Serial Number, you can manually enter the information, or capture it using a bar code scanner or similar device.\nLetters in the serial number must be in UPPER CASE.\nAlternatively, you may be able to reach out to the Sierra Wireless Partner you purchased your gateways from and request a list of the Serial Numbers and IMEIs of the gateways they have shipped you.\nOnce your spreadsheet is populated, save it as a CSV file somewhere accessible.\nIn ALMS, click\nSelect a CSV\nand select the CSV file you just saved.\nThe file will be identified. Select\nPre-configure Systems\n.\nWhen you click\nPre-configure Systems\n, a secondary dialog will appear. Make the following selections:\nTurn on\nHeartbeat\nand\nStatus report\n. Set the frequency to something appropriate for the communication you want the gateways to have. In this example, it was set to 15 minutes. More frequent is better for this initial configuration, and you can always reset the communication frequency from ALMS after the gateways are set up.\nFor\nInstall firmware\n, select the most recent version for your gateway. This will force the gateways to update to the latest version, when they check in.\nFor\nApply template\n, select the template you just created in ALMS.\nClick\nPre-configure\n.\nYou are presented with a summary screen that confirms all your choices. Click\nStart\n.\nThe file will upload, and your devices will be registered in ALMS, ready for them to communicate for the first time.\nConfiguring Multiple Gateways\nAt this stage, you will want to get your hardware environment set up. Ideally, you will have access to a bench area where you can set-up a multi-port Ethernet switch, along with power supplies for the gateways. Please note that many AirLink gateways are designed for industrial or mobile environments and do not ship with an AC power supply. Speak with your Sierra Wireless Partner to order the power supplies needed for your model(s) of gateways. If this process is one where you will be repeating this task on a regular basis, consider a permanent set-up where you leave the Ethernet cables and power supplies plugged in permanently. This will allow you to swap gateways in and out quickly and easily.\nWhen assessing your network configuration, please note that the devices must also be able to access a DHCP server that will serve up an IP address and allow them to access the Internet. In our default configuration, the DHCP Mode in ALEOS is set to \u201CAuto\u201D. If the device does not see a DHCP server on its Ethernet connection after a period of time, it will switch the DHCP mode back to the gateway being a DHCP server, which will prevent this process from working correctly.\nLeave the Ethernet switch and power supplies turned off. Plug in the power supply and Ethernet cable to each modem. In this example, we had 11 gateways plugged into a 24 port switch. There is essentially no limit to how many you can configure simultaneously, although there are practical limits.\nOnce all the gateways are plugged in to power and Ethernet, and you have confirmed that you can access the Internet through the switch, turn on the power to the gateways and the switch.\nAt this stage the gateways will power up and access the Internet. By default, they will connect to ALMS and received instructions from ALMS to update to the latest firmware, and apply the template you have selected. You will observe the gateways reboot a number of times during this process.\nLog into ALMS to see the gateway operations progress, or you can walk away and leave them to complete their installations, upgrades and configuration. The whole process should take a little more than 30 minutes.\nAfter sufficient time, you can log in to ALMS to confirm that your devices have successfully completed the configuration process"})]})}function h(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},8453(e,t,a){a.d(t,{R:()=>i,x:()=>s});var n=a(6540);let o={},r=n.createContext(o);function i(e){let t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);